# Neurosky MindWave Integration
import socket

class MindWaveReader:
    def __init__(self, host='127.0.0.1', port=13854):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.connect((host, port))

        # Configure
        config = {"enableRawOutput": True, "format": "Json"}
        self.socket.send(json.dumps(config).encode())

    def read_attention(self):
        data = self.socket.recv(1024).decode()
        if data:
            return json.loads(data).get('eSense', {}).get('attention')
        return None
